const headers = [
  'id','name','price','category','description','image','active','sort_order',
  'product_prompt','workflow_status','qa_status','source_drive_id',
  'processed_image','review_reason','sku','age_min','age_max'
];

const escapeCsv = (value) => {
  if (value === null || value === undefined) return '';
  const text = String(value);
  if (/[\",\n\r]/.test(text)) {
    return `\"${text.replace(/\"/g, '\"\"')}\"`;
  }
  return text;
};

const rows = $input.all()
  .map(i => i.json)
  .filter(r =>
    String(r.active || '').toUpperCase() === 'TRUE' &&
    String(r.workflow_status || '').toUpperCase() === 'PUBLISHED' &&
    String(r.qa_status || '').toUpperCase() === 'PASS' &&
    String(r.id || '').trim() &&
    String(r.name || '').trim() &&
    String(r.image || '').trim()
  )
  .map(r => ({
    id: r.id,
    name: r.name,
    price: r.price ?? '',
    category: r.category || '',
    description: r.description || '',
    image: r.image || '',
    active: 'TRUE',
    sort_order: r.sort_order || '',
    product_prompt: r.product_prompt || '',
    workflow_status: 'PUBLISHED',
    qa_status: 'PASS',
    source_drive_id: r.source_drive_id || '',
    processed_image: r.processed_image || '',
    review_reason: '',
    sku: r.sku || '',
    age_min: r.age_min ?? '',
    age_max: r.age_max ?? ''
  }))
  .sort((a,b) => String(a.id).localeCompare(String(b.id)));

const lines = [
  headers.join(','),
  ...rows.map(row => headers.map(h => escapeCsv(row[h])).join(','))
];

const text = lines.join('\n') + '\n';

return [{
  json: {
    count: rows.length,
    content_b64: Buffer.from(text, 'utf8').toString('base64'),
    commit_message: `chore(catalog): sync ${rows.length} approved products`
  }
}];
